const $ = s => document.querySelector(s);
const bookmark = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 4h12v17l-6-4-6 4z"/></svg>';
const COVER = Object.fromEntries(STORIES.map(s=>[s.id,s.coverURL]));
const orderedStories = [...STORIES];
const worldNames = {all:'Tonight’s open doors',history:'The ancient world awaits',science:'A universe to discover',nature:'Wonders of the wild',saved:'Your story shelf'};
const glyph = {pyramid:'△',moon:'☾',earth:'◎',fireflies:'✧'};
let world='all', current=null, libraryScroll=0, narrating=false, speech=null, toastTimer, progressFrame=0;
function readStore(key,fallback) { try { return JSON.parse(localStorage.getItem(key)) ?? fallback; } catch { return fallback; } }
const storedShelf=readStore('little-wonders-shelf',[]),storedFinished=readStore('little-wonders-finished',[]);
const saved=new Set((Array.isArray(storedShelf)?storedShelf:[]).filter(id=>STORIES.some(s=>s.id===id)));
const finished=new Set(Array.isArray(storedFinished)?storedFinished:[]);
function writeStore(key,value) { try { localStorage.setItem(key,JSON.stringify(value)); return true; } catch { return false; } }
function notify(message) { $('#toast').textContent=message; $('#toast').classList.add('visible'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2400); }
function updateSavedButtons() {
 $('#savedCount').textContent=saved.size;
 document.querySelectorAll('[data-save]').forEach(b=>{ const yes=saved.has(b.dataset.save); b.classList.toggle('saved',yes); b.setAttribute('aria-pressed',yes); b.setAttribute('aria-label',`${yes?'Remove':'Save'} ${STORIES.find(s=>s.id===b.dataset.save).plainTitle}${yes?' from':' to'} story shelf`); });
}
function toggleSave(id) { const yes=!saved.has(id); yes?saved.add(id):saved.delete(id); const persisted=writeStore('little-wonders-shelf',[...saved]); updateSavedButtons(); if(world==='saved'&&!current)renderLibrary(); notify(persisted?(yes?'Saved for another lovely night':'Removed from your story shelf'):'Saved for this visit; browser storage is unavailable.'); }
function storyMeta(s) { return `<div class="story-meta">${s.label}<span>·</span><span class="time">${s.minutes} MIN READ</span></div>`; }
function readLink(s) { return `<a class="read-story" href="#story/${s.id}">${finished.has(s.id)?'Read again':'Read story'}<span class="arrow">↗</span></a>`; }
function renderLibrary() {
 const query=$('#search').value.trim().toLowerCase();
 const matches=orderedStories.filter(s=>(world==='all'||(world==='saved'?saved.has(s.id):s.category===world))&&`${s.plainTitle} ${s.label} ${s.place} ${s.description}`.toLowerCase().includes(query)).slice(0,10);
 $('#collectionTitle').textContent=worldNames[world]; $('#resultCount').textContent=`${matches.length} ${matches.length===1?'story':'stories'}`;
 $('#storyGrid').innerHTML=matches.map(s=>COVER[s.id]?`<article class="story-door"><div class="door-frame"><a class="portal-image" href="#story/${s.id}" aria-label="Read ${s.plainTitle}"><img src="${COVER[s.id]}" alt="${s.alt}" ${s.id==='pyramid'?'fetchpriority="high"':'loading="lazy"'}><span class="portal-badge" aria-hidden="true">${glyph[s.id] || ({history:'△',science:'☾',nature:'✧'}[s.category])}</span><span class="portal-note">${s.id==='pyramid'?'Step into ancient Egypt':'Journey beyond Earth'}</span></a><button class="save-door" data-save="${s.id}">${bookmark}</button></div><div class="story-copy">${storyMeta(s)}<h3><a href="#story/${s.id}">${s.title}</a></h3><p>${s.description}</p><div class="door-bottom">${readLink(s)}<span class="volume-number">VOLUME ${String(orderedStories.indexOf(s)+1).padStart(2,'0')} ${finished.has(s.id)?'· READ':'· ILLUSTRATED'}</span></div></div></article>`:`<article class="quiet-story"><a class="quiet-cover ${s.id==='earth'?'earth-cover':''}" href="#story/${s.id}" aria-label="Read ${s.plainTitle}"><span class="cover-icon" aria-hidden="true">${glyph[s.id] || ({history:'△',science:'☾',nature:'✧'}[s.category])}</span><span class="cover-name">${s.id==='earth'?'A shadow.<br>A whole world.':'Little lights.<br>Big secrets.'}</span><span class="cover-mark">LITTLE WONDERS</span></a><div class="story-copy"><button class="quiet-save" data-save="${s.id}">${bookmark}</button>${storyMeta(s)}<h3><a href="#story/${s.id}">${s.plainTitle}</a></h3><p>${s.description}</p>${readLink(s)}</div></article>`).join('');
 document.querySelectorAll('.story-door').forEach(card=>{const title=card.querySelector('.story-copy h3');title.className='portal-title';title.innerHTML=title.querySelector('a').innerHTML;card.querySelector('.portal-image').append(title);card.querySelector('.portal-note').innerHTML='Read story <b>↗</b>';});
 $('#empty').hidden=matches.length>0; $('#emptyTitle').textContent=world==='saved'&&!query?'Your shelf is waiting.':'A wonder is waiting.';
 $('#emptyDescription').textContent=world==='saved'&&!query?'Tap the bookmark on a story to keep it for another night.':'No stories match that search. Try “Moon”, “Egypt”, or explore every door.';
 document.querySelectorAll('[data-world]').forEach(b=>{b.classList.toggle('active',b.dataset.world===world);b.setAttribute('aria-pressed',b.dataset.world===world);}); updateSavedButtons();
}
function stopSpeech() { if('speechSynthesis' in window)speechSynthesis.cancel(); speech=null; narrating=false; const b=$('#readAloud'); if(b){b.innerHTML='▷ <span>Read aloud</span>';b.setAttribute('aria-pressed','false');} }
function toggleSpeech() { if(!current||!('speechSynthesis' in window))return; if(narrating){stopSpeech();return;} speech=new SpeechSynthesisUtterance(`${current.plainTitle}. ${current.chapters.map(c=>c.title+'. '+c.paragraphs.join(' ')).join(' ')}`);speech.lang='en-US';speech.rate=.86;speech.onend=stopSpeech;speech.onerror=e=>{stopSpeech();if(!['interrupted','canceled'].includes(e.error))notify('Read-aloud is unavailable on this device.');};narrating=true;$('#readAloud').innerHTML='■ <span>Stop reading</span>';$('#readAloud').setAttribute('aria-pressed','true');speechSynthesis.speak(speech); }
function renderReader(story) {
 current=story; stopSpeech(); const illustrated=!!COVER[story.id];
 $('#readingRoom').innerHTML=`<header class="reader-header"><a class="back-library" href="#library"><span>←</span>Back to the library</a><a class="reader-wordmark" href="#library"><i>✧</i> little wonders.</a><div class="reader-tools"><button id="readAloud" aria-pressed="false">▷ <span>Read aloud</span></button><button id="fontSize" aria-label="Increase reading text size">Aa</button><button class="reader-save" data-save="${story.id}">${bookmark}<span>Save story</span></button></div><div class="reading-progress" aria-hidden="true"><span id="progressFill"></span></div></header><section class="story-panorama ${illustrated?'':`text-panorama ${story.id}`}" aria-labelledby="storyTitle">${illustrated?`<img src="${COVER[story.id]}" alt="${story.alt}">`:''}<div class="panorama-title"><p class="eyebrow">${story.place}</p><h1 id="storyTitle">${story.plainTitle}</h1><p>${story.deck}</p><div class="panorama-meta"><span>${story.minutes} MIN READ</span><span>✦</span><span>READ TOGETHER</span><span>✦</span><span>A TRUE-WORLD ADVENTURE</span></div></div></section><div class="reading-layout"><article class="story-article">${story.chapters.map((c,i)=>`<section class="story-chapter" id="chapter-${i+1}"><div class="chapter-eyebrow">CHAPTER 0${i+1}</div><h2>${c.title}</h2>${c.paragraphs.map((p,j)=>`<p id="${c.paragraphIDs[j]}" data-paragraph>${p}</p>`).join('')}${i<story.chapters.length-1?'<div class="chapter-separator" aria-hidden="true">✦</div>':''}</section>`).join('')}<aside class="source-note"><h3>A little note for grown-ups</h3><p>${story.note}${illustrated?' The cover is an artistic interpretation, including illustrative scale and scenery.':''}</p><div class="source-links">${story.sources.map(([title,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${title} ↗</a>`).join('')}</div></aside><div class="story-end"><span aria-hidden="true">✧</span><h3>A little more world.<br>A little more wonder.</h3><p>Another door is waiting when you’re ready.</p><div class="story-end-buttons"><a class="gold-button" href="#library">Find another story <span>↗</span></a><button class="finish-button" id="markFinished">${finished.has(story.id)?'✓ Adventure completed':'Mark as read ✓'}</button></div></div></article><aside class="reading-aside"><span class="contents-label">INSIDE THIS STORY</span><nav class="contents-nav" aria-label="Story chapters">${story.chapters.map((c,i)=>`<a href="#chapter-${i+1}" data-chapter="chapter-${i+1}"><span>0${i+1}</span>${c.title}</a>`).join('')}</nav><div class="aside-note"><span>☾</span><p>Find a cozy corner.<br>Let the world<br>come to you.</p><small>The whole story is here.<br>Read at your own pace.</small></div></aside></div><footer class="reader-foot">✧ little wonders.</footer>`;
 $('#readAloud').disabled=!story.audio&&!('speechSynthesis' in window); if($('#readAloud').disabled)$('#readAloud').innerHTML='Voice unavailable';
 updateSavedButtons(); updateProgress();
}
function route() {
 const match=location.hash.match(/^#(?:story\/|story-)([a-z0-9_-]+)$/); const story=match&&STORIES.find(s=>s.id===match[1]);
 if(story){if(!current)libraryScroll=window.scrollY;$('#library').hidden=true;$('#readingRoom').hidden=false;renderReader(story);window.scrollTo({top:0,behavior:'instant'});document.title=story.plainTitle+' · Little Wonders';$('#storyTitle').setAttribute('tabindex','-1');$('#storyTitle').focus({preventScroll:true});}
 else {stopSpeech(); const wasReading=!!current;current=null;$('#readingRoom').hidden=true;$('#library').hidden=false;renderLibrary();document.title='Little Wonders · A world between the pages';if(wasReading)window.scrollTo({top:libraryScroll,behavior:'instant'});}
}
function updateProgress() { if(!current)return; const article=$('.story-article'); const start=article.getBoundingClientRect().top+window.scrollY;const end=start+article.offsetHeight-window.innerHeight+100;const percent=Math.max(0,Math.min(100,(window.scrollY-start+100)/(end-start)*100));$('#progressFill').style.width=percent+'%';const sections=[...document.querySelectorAll('.story-chapter')];let active=sections[0]?.id;for(const c of sections)if(c.getBoundingClientRect().top<180)active=c.id;document.querySelectorAll('[data-chapter]').forEach(a=>{a.classList.toggle('active',a.dataset.chapter===active);if(a.dataset.chapter===active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});}
document.addEventListener('click',e=>{
 const save=e.target.closest('[data-save]');if(save)toggleSave(save.dataset.save);
 const category=e.target.closest('[data-world]');if(category){world=category.dataset.world;renderLibrary();}
 const anchor=e.target.closest('[data-chapter]');if(anchor){e.preventDefault();$('#'+anchor.dataset.chapter).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});}
 if(e.target.closest('#readAloud'))toggleSpeech();
 if(e.target.closest('#fontSize')){document.body.classList.toggle('large-type');$('#fontSize').setAttribute('aria-label',document.body.classList.contains('large-type')?'Use standard reading text size':'Increase reading text size');}
 if(e.target.closest('#markFinished')){finished.add(current.id);writeStore('little-wonders-finished',[...finished]);$('#markFinished').textContent='✓ Adventure completed';notify('One more adventure. A little more wonder.');}
});
$('#search').addEventListener('input',renderLibrary);$('#resultCount').setAttribute('aria-live','polite');
$('#resetFilters').addEventListener('click',()=>{world='all';$('#search').value='';renderLibrary();});
$('#surprise').addEventListener('click',()=>location.hash='story/'+orderedStories[Math.floor(Math.random()*orderedStories.length)].id);
$('#aboutButton').addEventListener('click',()=>$('#about').showModal());$('#closeAbout').addEventListener('click',()=>$('#about').close());$('#aboutExplore').addEventListener('click',()=>$('#about').close());
$('#about').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close();}});
function setBedtime(on){document.body.classList.toggle('bedtime',on);$('#bedtimeButton').setAttribute('aria-pressed',on);}
setBedtime(readStore('little-wonders-bedtime',false)===true||localStorageSafeOldMode());
function localStorageSafeOldMode(){try{return localStorage.getItem('little-wonders-bedtime')==='1';}catch{return false;}}
$('#bedtimeButton').addEventListener('click',()=>{const on=!document.body.classList.contains('bedtime');setBedtime(on);writeStore('little-wonders-bedtime',on);notify(on?'The lights are low. The stories are waiting.':'The library lanterns are bright again.');});
window.addEventListener('hashchange',()=>{if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion:reduce)').matches)document.startViewTransition(route);else route();});window.addEventListener('scroll',()=>{if(!progressFrame)progressFrame=requestAnimationFrame(()=>{progressFrame=0;updateProgress();});},{passive:true});document.addEventListener('visibilitychange',()=>{if(document.hidden && !current?.audio)stopSpeech();});route();

